"""
Configurable wait policies for rollup partition mappers.

A :class:`WaitPolicy` decides, given the set of upstream partition keys that
have actually arrived (``matched``) and the full set the rollup window declares
(``expected``), whether the downstream Dag run should fire yet. It also reports
whether the policy can *ever* be satisfied for a window of a given size, so the
scheduler can stop holding a Dag run that is permanently unreachable.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Optional


@dataclass
class PartitionSatisfaction:
    """
    Result of evaluating a :class:`WaitPolicy` against a set of arrived keys.

    ``satisfied`` — the downstream Dag run may fire now.
    ``unreachable`` — the policy can never be satisfied for this window; the
    scheduler should stop holding the run and warn.
    ``unreachable_reason`` — human-readable explanation, required iff
    ``unreachable`` is ``True`` and forbidden otherwise.
    """

    satisfied: bool
    unreachable: bool = False
    unreachable_reason: Optional[str] = None

    def __post_init__(self) -> None:
        if self.unreachable and self.unreachable_reason is None:
            raise ValueError("unreachable_reason must be set when unreachable=True")
        if not self.unreachable and self.unreachable_reason is not None:
            raise ValueError("unreachable_reason must be None when unreachable=False")


class WaitPolicy(ABC):
    """
    Abstract base class for rollup wait policies.

    Subclasses implement the count-based predicates :meth:`is_satisfied` and
    :meth:`is_unreachable`. The default :meth:`is_satisfied_by_keys` converts
    the arrived/expected key sets to counts and delegates to those predicates.
    """

    @abstractmethod
    def is_satisfied(self, matched: int, expected: int) -> bool:
        """Return whether *matched* arrived keys satisfy the policy for a window of *expected* keys."""

    @abstractmethod
    def is_unreachable(self, expected: int) -> bool:
        """Return whether the policy can never be satisfied for a window of *expected* keys."""

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        """
        Evaluate the policy against the arrived (*matched*) and declared (*expected*) key sets.

        Only keys that are both arrived *and* expected count toward satisfaction;
        stray keys outside the window are ignored.
        """
        expected_count = len(expected)
        if self.is_unreachable(expected_count):
            reason = (
                f"wait policy {self!r} can never be satisfied given the window's "
                f"cardinality {expected_count}"
            )
            return PartitionSatisfaction(satisfied=False, unreachable=True, unreachable_reason=reason)
        matched_count = len(matched & expected)
        return PartitionSatisfaction(satisfied=self.is_satisfied(matched_count, expected_count))


class WaitForAll(WaitPolicy):
    """
    Fire the downstream Dag run only once every declared upstream key has arrived.

    Stateless: all instances are equal and hash equal.
    """

    def __repr__(self) -> str:
        return "WaitForAll()"

    def __eq__(self, other: object) -> bool:
        return isinstance(other, WaitForAll)

    def __hash__(self) -> int:
        return hash(WaitForAll)

    def is_satisfied(self, matched: int, expected: int) -> bool:
        return matched == expected

    def is_unreachable(self, expected: int) -> bool:
        return False

    def is_satisfied_by_keys(self, matched: set, expected: set) -> PartitionSatisfaction:
        # Short-circuit: the run fires exactly when every expected key is present.
        return PartitionSatisfaction(satisfied=matched >= expected)


class MinimumCount(WaitPolicy):
    """
    Fire once at least *n* upstream keys have arrived.

    Positive ``n`` is an absolute threshold: fire when ``matched >= n``.
    Negative ``n`` is relative to the window size: fire when
    ``matched >= max(0, expected + n)`` (e.g. ``n=-3`` fires when all but three
    of the declared keys have arrived).
    """

    def __init__(self, n: int) -> None:
        if n == 0:
            raise ValueError("MinimumCount(0) is degenerate; use a positive or negative threshold")
        self.n = n

    def __repr__(self) -> str:
        return f"MinimumCount(n={self.n})"

    def __eq__(self, other: object) -> bool:
        return isinstance(other, MinimumCount) and self.n == other.n

    def __hash__(self) -> int:
        return hash(self.n)

    def is_satisfied(self, matched: int, expected: int) -> bool:
        if self.n > 0:
            return matched >= self.n
        return matched >= max(0, expected + self.n)

    def is_unreachable(self, expected: int) -> bool:
        # A positive absolute threshold larger than the window can never be met.
        # A relative (negative) threshold is clamped at 0, so it is always reachable.
        return self.n > 0 and self.n > expected
